{"path":"assets/css/styles.css","content":"/*
  Dental Premium Template Styles
  System font only. No external assets.
*/
:root {
  --brand-700: #0b5ac2;
  --brand-600: #1a6ce0;
  --brand-500: #2b7bff;
  --brand-400: #5a97ff;
  --mint-500: #1ec9a8;
  --mint-400: #37d8b8;
  --ink-900: #0b1b2b;
  --ink-700: #2a3b4e;
  --ink-600: #3b4f64;
  --ink-500: #516579;
  --ink-400: #6a7f94;
  --ink-300: #8ea1b3;
  --ink-200: #c2ced9;
  --ink-100: #e7eef5;
  --bg-50: #f6fbff;
  --bg-100: #eef6ff;
  --surface: #ffffff;
  --shadow: 0 1px 2px rgba(0,0,0,.06), 0 8px 24px rgba(12, 40, 72, .08);
  --radius: 14px;
  --radius-sm: 10px;
  --radius-xs: 8px;
  --container: 1200px;
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Oxygen, Ubuntu, Cantarell, "Helvetica Neue", Arial, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol";
  color: var(--ink-700);
  background: radial-gradient(1200px 600px at 80% -50%, rgba(43,123,255,.08), transparent 60%), var(--bg-50);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}
img, svg { max-width: 100%; height: auto; }

.container { width: min(100% - 2rem, var(--container)); margin-inline: auto; }
.section { padding: clamp(3rem, 5vw, 6rem) 0; }
.surface { background: var(--surface); border-radius: var(--radius); box-shadow: var(--shadow); }

h1, h2, h3 { color: var(--ink-900); line-height: 1.2; margin: 0 0 .6em; }
h1 { font-size: clamp(2rem, 3.4vw, 3rem); letter-spacing: -.01em; }
h2 { font-size: clamp(1.6rem, 2.6vw, 2.2rem); }
h3 { font-size: clamp(1.2rem, 2vw, 1.5rem); }
.lead { font-size: clamp(1.05rem, 1.2vw, 1.2rem); color: var(--ink-600); }

.btn { display: inline-flex; align-items: center; gap: .6rem; padding: .9rem 1.2rem; border-radius: 999px; border: 0; cursor: pointer; font-weight: 600; text-decoration: none; transition: transform .2s ease, box-shadow .2s ease, background .2s ease; }
.btn:focus-visible { outline: 3px solid color-mix(in oklab, var(--brand-500), white 70%); outline-offset: 2px; }
.btn-primary { background: linear-gradient(180deg, var(--brand-500), var(--brand-600)); color: #fff; box-shadow: 0 6px 18px rgba(43,123,255,.28); }
.btn-primary:hover { transform: translateY(-1px); box-shadow: 0 10px 28px rgba(43,123,255,.36); }
.btn-ghost { background: color-mix(in oklab, var(--brand-500), white 88%); color: var(--brand-700); }
.btn-ghost:hover { background: color-mix(in oklab, var(--brand-500), white 80%); }
.btn-link { background: transparent; color: var(--brand-700); padding: 0; }

.badge { display: inline-flex; align-items: center; gap:.4rem; padding: .35rem .7rem; border-radius: 999px; font-weight: 600; font-size: .82rem; color: var(--brand-700); background: color-mix(in oklab, var(--brand-500), white 85%); }

.kicker { text-transform: uppercase; letter-spacing: .12em; font-weight: 700; color: var(--brand-700); font-size: .8rem; }

.grid { display: grid; gap: 1.4rem; }
.grid-2 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.grid-3 { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.grid-4 { grid-template-columns: repeat(4, minmax(0, 1fr)); }
@media (max-width: 900px) {
  .grid-4 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 720px) {
  .grid-3, .grid-2, .grid-4 { grid-template-columns: 1fr; }
}

.card { background: var(--surface); border-radius: var(--radius); padding: 1.2rem; box-shadow: var(--shadow); }
.card-lg { padding: clamp(1.2rem, 2.5vw, 2rem); border-radius: calc(var(--radius) + 4px); }
.card .title { font-weight: 700; margin-bottom: .4rem; }
.card .meta { color: var(--ink-500); font-size: .95rem; }

.icon { width: 42px; height: 42px; border-radius: 10px; display: inline-grid; place-items: center; color: var(--brand-700); background: color-mix(in oklab, var(--brand-500), white 86%); }
.icon.mint { color: #0f6; background: color-mix(in oklab, var(--mint-500), white 86%); }

.hero { position: relative; padding: clamp(4rem, 7vw, 7rem) 0; overflow: clip; }
.hero::before { content: ""; position: absolute; inset: 0; background-image: url('../img/hero-abstract.svg'); background-size: cover; background-position: center; opacity: .28; filter: saturate(1.2) blur(0.2px); pointer-events: none; }
.hero .container { position: relative; z-index: 1; }
.hero h1 span { background: linear-gradient(90deg, var(--brand-600), var(--mint-500)); -webkit-background-clip: text; background-clip: text; color: transparent; }

.site-header { position: sticky; top: 0; z-index: 50; background: rgba(255,255,255,.85); backdrop-filter: saturate(1.2) blur(10px); border-bottom: 1px solid rgba(12,40,72,.06); transition: box-shadow .25s ease; }
.site-header.scrolled { box-shadow: 0 8px 28px rgba(12,40,72,.08); }
.topbar { font-size: .9rem; padding: .4rem 0; border-bottom: 1px solid rgba(12,40,72,.06); color: var(--ink-600); }
.topbar a { color: var(--brand-700); font-weight: 700; text-decoration: none; }

.navbar { display: flex; align-items: center; justify-content: space-between; gap: 1rem; padding: .8rem 0; }
.brand { display: flex; align-items: center; gap: .8rem; text-decoration: none; color: var(--ink-900); font-weight: 900; letter-spacing: .01em; }
.brand .logo { width: 40px; height: 40px; border-radius: 10px; display:grid; place-items:center; background: linear-gradient(160deg, var(--brand-500), var(--brand-700)); color: #fff; font-weight: 900; box-shadow: inset 0 0 10px rgba(255,255,255,.15); }
.brand small { font-weight: 600; color: var(--ink-500); display:block; margin-top: -4px; }

.nav { display: flex; align-items: center; gap: .6rem; }
.nav a { text-decoration: none; color: var(--ink-700); font-weight: 600; padding: .6rem .8rem; border-radius: 10px; }
.nav a[aria-current="page"] { color: var(--brand-700); background: color-mix(in oklab, var(--brand-500), white 88%); }

.nav-actions { display:flex; align-items:center; gap:.6rem; }
.menu-toggle { display:none; border:0; background: transparent; padding:.5rem; border-radius: 10px; }
.menu-toggle:focus-visible { outline: 3px solid color-mix(in oklab, var(--brand-500), white 70%); outline-offset: 2px; }
.menu-toggle svg { width: 26px; height: 26px; }

@media (max-width: 960px) {
  .menu-toggle { display:block; }
  .nav { position: fixed; inset: 64px 0 auto 0; top: calc(56px + 1px); background: rgba(255,255,255,.98); backdrop-filter: blur(10px); display: grid; grid-auto-rows: min-content; padding: 1rem; gap: .4rem; border-bottom: 1px solid rgba(12,40,72,.06); transform: translateY(-20px); opacity:0; visibility:hidden; transition: transform .2s ease, opacity .2s ease, visibility .2s ease; }
  .nav.open { transform: translateY(0); opacity:1; visibility: visible; }
}

.feature { display:flex; gap: 1rem; align-items: flex-start; }
.feature b { display:block; }

.divider { height: 1px; background: linear-gradient(90deg, transparent, rgba(12,40,72,.12), transparent); margin: 2rem 0; }

.list-check { list-style: none; padding: 0; margin: 0; display: grid; gap: .6rem; }
.list-check li { position: relative; padding-left: 1.9rem; }
.list-check li::before { content: "✓"; position: absolute; left: 0; top: .1rem; width: 1.2rem; height: 1.2rem; display: grid; place-items: center; border-radius: 999px; font-weight: 800; color: #fff; background: linear-gradient(180deg, var(--mint-500), #12b392); box-shadow: 0 4px 10px rgba(30,201,168,.25); }

.testimonial { display: grid; grid-template-columns: 56px 1fr; gap: 1rem; align-items: start; }
.testimonial .avatar { width: 56px; height: 56px; border-radius: 50%; background: color-mix(in oklab, var(--brand-500), white 86%); display:grid; place-items:center; overflow: hidden; }
.stars { color: #f59e0b; font-size: 1rem; letter-spacing: .05em; }

.faq dt { font-weight: 800; }
.faq dd { margin: 0 0 1rem 0; color: var(--ink-600); }

.table { width: 100%; border-collapse: collapse; background: var(--surface); border-radius: var(--radius); overflow: hidden; box-shadow: var(--shadow); }
.table th, .table td { padding: .9rem 1rem; text-align: left; }
.table thead th { background: color-mix(in oklab, var(--brand-500), white 92%); color: var(--ink-900); }
.table tbody tr:not(:last-child) td { border-bottom: 1px solid var(--ink-100); }

.form { display: grid; gap: 1rem; }
.input { display: grid; gap: .35rem; }
.input label { font-weight: 700; }
.input input, .input select, .input textarea { width: 100%; border: 1px solid var(--ink-200); border-radius: 12px; padding: .85rem 1rem; font: inherit; background:#fff; color: var(--ink-700); box-shadow: 0 1px 0 rgba(0,0,0,.02) inset; }
.input input:focus, .input select:focus, .input textarea:focus { outline: 3px solid color-mix(in oklab, var(--brand-500), white 70%); border-color: var(--brand-500); }
.input .help { font-size: .9rem; color: var(--ink-500); }

.notice { border-left: 4px solid var(--mint-500); padding: 1rem; background: color-mix(in oklab, var(--mint-500), white 92%); border-radius: var(--radius-xs); }
.alert { border-left: 4px solid #f59e0b; padding: 1rem; background: #fff8eb; border-radius: var(--radius-xs); }

.footer { background: linear-gradient(180deg, rgba(43,123,255,.06), rgba(30,201,168,.06)); border-top: 1px solid rgba(12,40,72,.08); margin-top: 3rem; }
.footer .grid { align-items: start; }
.footer a { color: inherit; text-decoration: none; }
.footer small, .legal { color: var(--ink-500); }

.map-placeholder { border-radius: var(--radius); background: linear-gradient(135deg, var(--ink-100), var(--bg-100)); border: 1px dashed var(--ink-200); min-height: 240px; display:grid; place-items:center; color: var(--ink-500); }

.sr-only { position: absolute !important; width: 1px !important; height: 1px !important; padding: 0 !important; margin: -1px !important; overflow: hidden !important; clip: rect(0, 0, 0, 0) !important; white-space: nowrap !important; border: 0 !important; }

hr.soft { height: 1px; border: 0; background: linear-gradient(90deg, transparent, rgba(12,40,72,.12), transparent); margin: 2rem 0; }

.tag-cloud { display:flex; flex-wrap:wrap; gap:.5rem; }
.tag-cloud .tag { padding: .5rem .8rem; background: color-mix(in oklab, var(--brand-500), white 90%); color: var(--brand-700); border-radius: 999px; font-weight: 600; font-size: .92rem; }

.quote { font-size: 1.1rem; font-weight: 600; color: var(--ink-800); border-left: 4px solid var(--brand-500); padding-left: 1rem; }

.inline-cta { display:flex; gap:.6rem; flex-wrap:wrap; align-items:center; }

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  * { transition: none !important; animation: none !important; }
}
"} 
{"path":"assets/js/main.js","content":"/* Dental Premium Template JS */
(function(){
  const header = document.querySelector('.site-header');
  const nav = document.querySelector('.nav');
  const toggle = document.querySelector('.menu-toggle');
  const yearEl = document.querySelector('[data-year]');

  function setYear(){ if(yearEl) yearEl.textContent = new Date().getFullYear(); }
  setYear();

  function onScroll(){
    if(!header) return;
    if(window.scrollY > 8){ header.classList.add('scrolled'); } else { header.classList.remove('scrolled'); }
  }
  window.addEventListener('scroll', onScroll, { passive: true });
  onScroll();

  if(toggle && nav){
    toggle.addEventListener('click', ()=>{
      const open = nav.classList.toggle('open');
      toggle.setAttribute('aria-expanded', String(open));
      if(open) nav.querySelector('a')?.focus();
    });
  }

  // Basic client-side form validation and success simulation
  document.querySelectorAll('form[data-enhanced]')?.forEach(form=>{
    form.addEventListener('submit', (e)=>{
      e.preventDefault();
      const submitBtn = form.querySelector('[type="submit"]');
      submitBtn?.setAttribute('disabled', 'true');
      submitBtn?.classList.add('sending');
      const invalid = form.querySelector(':invalid');
      if(invalid){
        invalid.focus();
        submitBtn?.removeAttribute('disabled');
        submitBtn?.classList.remove('sending');
        return;
      }
      setTimeout(()=>{
        alert('Thank you! Your submission has been received. We will contact you shortly at the details you provided.');
        submitBtn?.removeAttribute('disabled');
        submitBtn?.classList.remove('sending');
        form.reset();
      }, 600);
    });
  });

  // Set aria-current on matching nav link (for safety if not set)
  const path = location.pathname.split('/').pop() || 'index.html';
  document.querySelectorAll('.nav a').forEach(a=>{
    if(a.getAttribute('href') === path){ a.setAttribute('aria-current','page'); }
  });
})();
"} 
