{"path":"assets/img/hero-abstract.svg","content":"<svg xmlns="http://www.w3.org/2000/svg" width="1600" height="900" viewBox="0 0 1600 900" preserveAspectRatio="xMidYMid slice" role="img" aria-label="Abstract background">
  <defs>
    <linearGradient id="b" x1="0" x2="1" y1="0" y2="1">
      <stop offset="0" stop-color="#5a97ff"/>
      <stop offset="1" stop-color="#2bd4bd"/>
    </linearGradient>
    <radialGradient id="r" cx="80%" cy="-10%" r="90%">
      <stop offset="0" stop-color="#2b7bff" stop-opacity=".8"/>
      <stop offset="1" stop-color="#2bd4bd" stop-opacity=".2"/>
    </radialGradient>
    <filter id="f" x="-20%" y="-20%" width="140%" height="140%">
      <feTurbulence type="fractalNoise" baseFrequency="0.002 0.003" numOctaves="2" seed="8"/>
      <feColorMatrix type="saturate" values="0.6"/>
      <feGaussianBlur stdDeviation="20"/>
    </filter>
  </defs>
  <rect width="1600" height="900" fill="url(#r)"/>
  <g opacity=".35" filter="url(#f)">
    <path d="M0,640 C300,720 420,520 720,600 1000,676 1120,520 1460,580 L1600,620 1600,900 0,900Z" fill="url(#b)"/>
  </g>
  <g opacity=".25">
    <circle cx="240" cy="160" r="100" fill="#fff"/>
    <circle cx="420" cy="220" r="26" fill="#fff"/>
    <circle cx="1280" cy="140" r="60" fill="#fff"/>
  </g>
</svg>"} 
{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>{{BUSINESS_NAME}} | {{TAGLINE}}</title>
  <meta name="description" content="{{BUSINESS_NAME}} provides gentle, modern dentistry in {{CITY}}, {{STATE}}. Comprehensive care, compassionate team, and convenient hours. Call {{PHONE}}.">
  <link rel="canonical" href="index.html">
  <meta name="robots" content="index,follow">
  <meta name="theme-color" content="#2b7bff">
  <meta property="og:type" content="website">
  <meta property="og:title" content="{{BUSINESS_NAME}} | {{TAGLINE}}">
  <meta property="og:description" content="Gentle, modern dentistry in {{CITY}}, {{STATE}}. Comprehensive care with a smile.">
  <meta property="og:url" content="index.html">
  <meta property="og:image" content="assets/img/hero-abstract.svg">
  <meta name="twitter:card" content="summary_large_image">
  <meta name="twitter:title" content="{{BUSINESS_NAME}} | {{TAGLINE}}">
  <meta name="twitter:description" content="Gentle, modern dentistry in {{CITY}}, {{STATE}}.">
  <meta name="twitter:image" content="assets/img/hero-abstract.svg">
  <link rel="icon" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 64 64'%3E%3Cdefs%3E%3ClinearGradient id='a' x1='0' x2='1' y1='0' y2='1'%3E%3Cstop offset='0' stop-color='%235a97ff'/%3E%3Cstop offset='1' stop-color='%232bd4bd'/%3E%3C/linearGradient%3E%3C/defs%3E%3Cpath d='M22 10c6-4 14-4 20 0 8 6 12 22 4 36-4 7-16 10-24 0-9-12-8-30 0-36z' fill='url(%23a)'/%3E%3C/svg%3E">
  <link rel="stylesheet" href="assets/css/styles.css">
  <script defer src="assets/js/main.js"></script>
  <script type="application/ld+json">{
    "@context":"https://schema.org",
    "@type":"Dentist",
    "name":"{{BUSINESS_NAME}}",
    "description":"{{TAGLINE}}",
    "telephone":"{{PHONE}}",
    "email":"{{EMAIL}}",
    "image":"assets/img/hero-abstract.svg",
    "address":{
      "@type":"PostalAddress",
      "streetAddress":"{{ADDRESS}}",
      "addressLocality":"{{CITY}}",
      "addressRegion":"{{STATE}}",
      "postalCode":"{{ZIP}}"
    },
    "openingHours":"{{HOURS}}",
    "url":"index.html"
  }</script>
</head>
<body id="home">
  <a class="sr-only" href="#main">Skip to content</a>
  <header class="site-header" role="banner">
    <div class="topbar">
      <div class="container" style="display:flex;gap:.6rem;justify-content:space-between;align-items:center;flex-wrap:wrap;">
        <div>Call us: <a href="tel:{{PHONE}}" aria-label="Call us at {{PHONE}}">{{PHONE}}</a> • <span aria-label="Office hours">{{HOURS}}</span></div>
        <div><a class="badge" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a></div>
      </div>
    </div>
    <div class="container navbar" role="navigation" aria-label="Primary">
      <a href="index.html" class="brand">
        <span class="logo" aria-hidden="true">🦷</span>
        <span>
          {{BUSINESS_NAME}}
          <small>{{TAGLINE}}</small>
        </span>
      </a>
      <button class="menu-toggle" aria-expanded="false" aria-controls="site-menu" aria-label="Toggle menu">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><line x1="3" y1="6" x2="21" y2="6"/><line x1="3" y1="12" x2="21" y2="12"/><line x1="3" y1="18" x2="21" y2="18"/></svg>
      </button>
      <nav id="site-menu" class="nav">
        <a href="index.html" aria-current="page">Home</a>
        <a href="services.html">Services</a>
        <a href="insurance.html">Insurance</a>
        <a href="new-patient.html">New Patients</a>
        <a href="about.html">About</a>
        <a href="reviews.html">Reviews</a>
        <a href="book.html">Book</a>
        <a href="contact.html">Contact</a>
      </nav>
      <div class="nav-actions">
        <a class="btn btn-ghost" href="tel:{{PHONE}}">Call {{PHONE}}</a>
        <a class="btn btn-primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      </div>
    </div>
  </header>

  <main id="main">
    <section class="hero">
      <div class="container">
        <div class="grid grid-2" style="align-items:center;">
          <div>
            <span class="kicker">Your smile, our craft</span>
            <h1>Premium dental care in <span>{{CITY}}</span></h1>
            <p class="lead">From routine cleanings to smile makeovers, {{BUSINESS_NAME}} delivers comfort-first, technology-forward dentistry. Transparent pricing, on-time appointments, and results you can feel good about.</p>
            <div class="inline-cta" style="margin-top:1rem;">
              <a class="btn btn-primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
              <a class="btn btn-ghost" href="services.html">Explore services</a>
              <a class="btn btn-link" href="tel:{{PHONE}}">Or call {{PHONE}}</a>
            </div>
            <div class="divider"></div>
            <div class="grid grid-3">
              <div class="feature"><span class="icon">⌛</span><div><b>On-time promise</b><span class="meta">Your time matters. We run on schedule.</span></div></div>
              <div class="feature"><span class="icon mint">💠</span><div><b>Comfort-first</b><span class="meta">Gentle care, warm blankets, and music.</span></div></div>
              <div class="feature"><span class="icon">🧪</span><div><b>Modern tech</b><span class="meta">3D imaging, digital scans, and more.</span></div></div>
            </div>
          </div>
          <div class="surface card-lg">
            <h3>What to expect at your first visit</h3>
            <ul class="list-check">
              <li>Thorough exam and digital x‑rays as needed</li>
              <li>Gentle, comprehensive cleaning</li>
              <li>Personalized care plan with clear pricing</li>
            </ul>
            <div class="notice" style="margin-top:1rem;">
              New patient special: exam, x‑rays, and cleaning for one bundled price. Ask us for details at <a href="tel:{{PHONE}}">{{PHONE}}</a>.
            </div>
            <div style="margin-top:1rem; display:flex; gap:.6rem; flex-wrap:wrap;">
              <a class="btn btn-primary" href="new-patient.html">I'm a new patient</a>
              <a class="btn btn-ghost" href="insurance.html">Insurance & financing</a>
            </div>
          </div>
        </div>
      </div>
    </section>

    <section class="section">
      <div class="container">
        <div class="grid grid-3">
          <div class="card">
            <div class="icon" aria-hidden="true">🪥</div>
            <h3>Preventive care</h3>
            <p>Cleanings, exams, and periodontal maintenance to keep your smile healthy for life.</p>
            <a class="btn btn-link" href="services.html#preventive">Learn more →</a>
          </div>
          <div class="card">
            <div class="icon" aria-hidden="true">✨</div>
            <h3>Cosmetic dentistry</h3>
            <p>Whitening, bonding, and veneers crafted to your face for a natural, radiant look.</p>
            <a class="btn btn-link" href="services.html#cosmetic">Learn more →</a>
          </div>
          <div class="card">
            <div class="icon" aria-hidden="true">🛠️</div>
            <h3>Restorative solutions</h3>
            <p>Tooth-colored fillings, crowns, implants, and more—built to last and feel great.</p>
            <a class="btn btn-link" href="services.html#restorative">Learn more →</a>
          </div>
        </div>
      </div>
    </section>

    <section class="section" aria-labelledby="home-insurance">
      <div class="container surface card-lg">
        <div class="grid grid-2" style="align-items:center;">
          <div>
            <h2 id="home-insurance">Insurance made easy</h2>
