  <main id="main">
    <section class="hero">
      <div class="container">
        <h1>Patients love {{BUSINESS_NAME}}</h1>
        <p class="lead">We’re honored by your kind words and recommendations. Here are a few recent reviews.</p>
      </div>
    </section>

    <section class="section">
      <div class="container grid grid-3">
        <article class="card" itemprop="review" itemscope itemtype="https://schema.org/Review">
          <div class="stars" aria-label="5 out of 5 stars">★★★★★</div>
          <p itemprop="reviewBody">I used to dread the dentist—now I actually look forward to my cleanings. So gentle and thorough.</p>
          <div class="testimonial">
            <div class="avatar"><img src="assets/img/avatar-01.svg" alt="Reviewer avatar"></div>
            <div><b itemprop="author">Marisol G.</b><div class="meta">Preventive care</div></div>
          </div>
        </article>
        <article class="card" itemprop="review" itemscope itemtype="https://schema.org/Review">
          <div class="stars" aria-label="5 out of 5 stars">★★★★★</div>
          <p itemprop="reviewBody">Transparent pricing and no pressure. My crown looks and feels like a real tooth.</p>
          <div class="testimonial">
            <div class="avatar"><img src="assets/img/avatar-01.svg" alt="Reviewer avatar"></div>
            <div><b itemprop="author">Evan L.</b><div class="meta">Crown</div></div>
          </div>
        </article>
        <article class="card" itemprop="review" itemscope itemtype="https://schema.org/Review">
          <div class="stars" aria-label="5 out of 5 stars">★★★★★</div>
          <p itemprop="reviewBody">The team worked magic with two veneers—subtle, natural, and just right.</p>
          <div class="testimonial">
            <div class="avatar"><img src="assets/img/avatar-01.svg" alt="Reviewer avatar"></div>
            <div><b itemprop="author">Priya S.</b><div class="meta">Veneers</div></div>
          </div>
        </article>
        <article class="card" itemprop="review" itemscope itemtype="https://schema.org/Review">
          <div class="stars" aria-label="5 out of 5 stars">★★★★★</div>
          <p itemprop="reviewBody">Same‑day emergency relief. I called at 8am and was seen by 10am.</p>
          <div class="testimonial">
            <div class="avatar"><img src="assets/img/avatar-01.svg" alt="Reviewer avatar"></div>
            <div><b itemprop="author">Chris D.</b><div class="meta">Emergency visit</div></div>
          </div>
        </article>
        <article class="card" itemprop="review" itemscope itemtype="https://schema.org/Review">
          <div class="stars" aria-label="5 out of 5 stars">★★★★★</div>
          <p itemprop="reviewBody">I’ve never had a provider explain things so clearly. I finally understand what’s going on.</p>
          <div class="testimonial">
            <div class="avatar"><img src="assets/img/avatar-01.svg" alt="Reviewer avatar"></div>
            <div><b itemprop="author">Nate R.</b><div class="meta">Consultation</div></div>
          </div>
        </article>
        <article class="card" itemprop="review" itemscope itemtype="https://schema.org/Review">
          <div class="stars" aria-label="5 out of 5 stars">★★★★★</div>
          <p itemprop="reviewBody">The hygienist was wonderfully gentle. Left feeling fresh and informed.</p>
          <div class="testimonial">
            <div class="avatar"><img src="assets/img/avatar-01.svg" alt="Reviewer avatar"></div>
            <div><b itemprop="author">Gloria P.</b><div class="meta">Cleaning</div></div>
          </div>
        </article>
      </div>
    </section>

